"""Tests for embedded video support (typ2pptx.core.video)."""
import zipfile

import pytest
from pptx import Presentation
from pptx.util import Emu

from typ2pptx.core.video import (
    VideoPlacement, embed_videos, query_videos, _video_mime_type,
)

from .conftest import OUTPUT_DIR, PROJECT_DIR, TYP_SOURCES_DIR

# Generated by the video_assets fixture (no binary fixtures in the repo).
# Paths are relative to the repository root, the Typst root of video_test.typ.
ASSETS = OUTPUT_DIR / "video_assets"
CLIP = "tests/output/video_assets/clip.mp4"
POSTER = "tests/output/video_assets/clip.jpg"
# typ2pptx only copies the video bytes into the package, so the content does
# not have to be a playable MP4.
CLIP_BYTES = b"\x00\x00\x00\x18ftypmp42" + bytes(range(256))
EMU_PER_PT = 9525.0
P14 = "{http://schemas.microsoft.com/office/powerpoint/2010/main}"
A = "{http://schemas.openxmlformats.org/drawingml/2006/main}"


@pytest.fixture(scope="module", autouse=True)
def video_assets():
    from PIL import Image
    ASSETS.mkdir(parents=True, exist_ok=True)
    Image.new("RGB", (320, 180), (37, 99, 235)).save(ASSETS / "clip.jpg", quality=80)
    (ASSETS / "clip.mp4").write_bytes(CLIP_BYTES)
    return ASSETS


def _movies(slide):
    return [s for s in slide.shapes if s._element.find(f".//{A}videoFile") is not None]


def _pictures(slide):
    return [s for s in slide.shapes
            if s.shape_type == 13 and s._element.find(f".//{A}videoFile") is None]


def _box(shape):
    return (shape.left, shape.top, shape.width, shape.height)


def _deck_with_poster(placement):
    """One blank slide with the poster picture where typ2pptx would put it."""
    prs = Presentation()
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    box = [Emu(round(c * EMU_PER_PT)) for c in
           (placement.x, placement.y, placement.width, placement.height)]
    slide.shapes.add_picture(str(ASSETS / "clip.jpg"), *box)
    slide.shapes.add_textbox(0, 0, Emu(100000), Emu(100000))  # drawn above the poster
    return prs, slide


PLACEMENT = VideoPlacement(src=CLIP, poster=POSTER, page=1,
                           x=100.0, y=50.25, width=283.4646, height=159.4488)


class TestVideoPlacement:

    def test_from_metadata(self):
        v = VideoPlacement.from_metadata({
            "src": "a.mp4", "poster": "a.jpg", "page": 2,
            "x": 1, "y": 2.5, "width": 3, "height": 4,
        })
        assert v == VideoPlacement("a.mp4", 2, 1.0, 2.5, 3.0, 4.0, poster="a.jpg")

    @pytest.mark.parametrize("name,mime", [
        ("a.mp4", "video/mp4"), ("a.MOV", "video/quicktime"), ("a.m4v", "video/mp4"),
    ])
    def test_mime_type(self, name, mime):
        from pathlib import Path
        assert _video_mime_type(Path(name)) == mime


class TestEmbedVideos:

    def test_replaces_poster_in_place(self):
        prs, slide = _deck_with_poster(PLACEMENT)
        poster_index = list(slide.shapes).index(_pictures(slide)[0])

        report = embed_videos(prs, [PLACEMENT], str(PROJECT_DIR), EMU_PER_PT)

        assert report[0]["status"] == "embedded"
        movies = _movies(slide)
        assert len(movies) == 1
        assert _pictures(slide) == []
        assert _box(movies[0]) == tuple(
            round(c * EMU_PER_PT) for c in (100.0, 50.25, 283.4646, 159.4488))
        # z-order: the movie takes the poster's slot, below the later textbox
        assert list(slide.shapes).index(movies[0]) == poster_index

    def test_media_is_embedded(self, tmp_path):
        prs, _ = _deck_with_poster(PLACEMENT)
        embed_videos(prs, [PLACEMENT], str(PROJECT_DIR), EMU_PER_PT)
        out = tmp_path / "video.pptx"
        prs.save(out)

        with zipfile.ZipFile(out) as z:
            media = [n for n in z.namelist() if n.endswith(".mp4")]
            assert media == ["ppt/media/media1.mp4"]
            assert z.read(media[0]) == CLIP_BYTES
            types = z.read("[Content_Types].xml").decode()
            assert 'ContentType="video/mp4"' in types
            rels = z.read("ppt/slides/_rels/slide1.xml.rels").decode()
            assert "../media/media1.mp4" in rels
            assert 'TargetMode="External"' not in rels

        slide = Presentation(out).slides[0]
        movie = _movies(slide)[0]
        assert movie._element.find(f".//{P14}media") is not None
        timing = slide._element.find(
            "{http://schemas.openxmlformats.org/presentationml/2006/main}timing")
        assert timing is not None  # click-to-play media node

    def test_skips_page_without_poster(self):
        prs = Presentation()
        prs.slides.add_slide(prs.slide_layouts[6])
        report = embed_videos(prs, [PLACEMENT], str(PROJECT_DIR), EMU_PER_PT)
        assert report[0]["status"] == "skipped"
        assert _movies(prs.slides[0]) == []

    def test_skips_page_out_of_range(self):
        prs, slide = _deck_with_poster(PLACEMENT)
        v = VideoPlacement(**{**PLACEMENT.__dict__, "page": 5})
        assert embed_videos(prs, [v], str(PROJECT_DIR), EMU_PER_PT)[0]["status"] == "skipped"
        assert _movies(slide) == []

    def test_missing_video_file(self):
        prs, _ = _deck_with_poster(PLACEMENT)
        v = VideoPlacement(**{**PLACEMENT.__dict__, "src": "missing.mp4"})
        with pytest.raises(FileNotFoundError):
            embed_videos(prs, [v], str(PROJECT_DIR), EMU_PER_PT)


@pytest.fixture(scope="module")
def video_test_typ():
    return TYP_SOURCES_DIR / "video_test.typ"


@pytest.fixture(scope="module")
def video_pptx(video_test_typ, typst_ts_cli, output_dir):
    from typ2pptx.core.converter import convert_typst_to_pptx
    out = output_dir / "video_test.pptx"
    convert_typst_to_pptx(str(video_test_typ), str(out), typst_ts_cli=typst_ts_cli,
                          root=str(PROJECT_DIR))
    return Presentation(out), out


class TestVideoPipeline:
    """Touying deck -> typst-ts-cli SVG -> PPTX with embedded videos."""

    def test_metadata(self, video_test_typ):
        videos = query_videos(str(video_test_typ), root=str(PROJECT_DIR))
        # pause: the hidden first subslide still carries the metadata
        assert [v.page for v in videos] == [2, 3, 4, 5]
        assert videos[0].width == pytest.approx(283.4646, abs=1e-3)

    def test_slide_count(self, video_pptx):
        prs, _ = video_pptx
        assert len(prs.slides) == 5

    def test_movies_per_slide(self, video_pptx):
        prs, _ = video_pptx
        assert [len(_movies(s)) for s in prs.slides] == [0, 1, 1, 0, 1]

    def test_posters_replaced(self, video_pptx):
        prs, _ = video_pptx
        for i in (1, 2, 4):
            assert _pictures(prs.slides[i]) == []

    def test_positions_match_metadata(self, video_pptx, video_test_typ):
        prs, _ = video_pptx
        videos = query_videos(str(video_test_typ), root=str(PROJECT_DIR))
        for v in videos:
            movies = _movies(prs.slides[v.page - 1])
            if v.page == 4:  # hidden subslide
                assert movies == []
                continue
            want = tuple(round(c * EMU_PER_PT) for c in (v.x, v.y, v.width, v.height))
            assert _box(movies[0]) == want

    def test_single_media_part(self, video_pptx):
        _, out = video_pptx
        with zipfile.ZipFile(out) as z:
            assert [n for n in z.namelist() if n.endswith(".mp4")] == ["ppt/media/media1.mp4"]

    def test_disabled(self, video_test_typ, typst_ts_cli, output_dir):
        from typ2pptx.core.converter import ConversionConfig, convert_typst_to_pptx
        out = output_dir / "video_test_disabled.pptx"
        convert_typst_to_pptx(str(video_test_typ), str(out), typst_ts_cli=typst_ts_cli,
                              root=str(PROJECT_DIR),
                              config=ConversionConfig(embed_videos=False))
        prs = Presentation(out)
        assert sum(len(_movies(s)) for s in prs.slides) == 0
        assert len(_pictures(prs.slides[1])) == 1
